        public void Configure(Transform scenePlayer,Transform sceneFirePoint,Transform sceneGridOrigin,Transform sceneBlocksRoot,Transform sceneProjectilesRoot,LineRenderer scenePreview,GameObject normal,GameObject gem,GameObject bomb,GameObject projectile,Text hpLabel,Text scoreLabel,Text gemLabel,Text turnLabel,Text comboLabel,Text levelLabel,Text characterLabel,Text overLabel,GameObject pause,GameObject over,GameObject upgrades,GameObject characters){player=scenePlayer;firePoint=sceneFirePoint;gridOrigin=sceneGridOrigin;blocksRoot=sceneBlocksRoot;projectilesRoot=sceneProjectilesRoot;aimPreview=scenePreview;normalBlockPrefab=normal;gemBlockPrefab=gem;bombBlockPrefab=bomb;projectilePrefab=projectile;hpText=hpLabel;scoreText=scoreLabel;gemsText=gemLabel;turnText=turnLabel;comboText=comboLabel;levelText=levelLabel;characterText=characterLabel;gameOverText=overLabel;pausePanel=pause;gameOverPanel=over;upgradePanel=upgrades;characterPanel=characters;}
        void Awake()
        {
            if (ValidatePersistentReferences()) return;
            enabled = false;
            Debug.LogError("ReflectableGameController disabled because the saved Game scene has missing persistent references.", this);
        }
        void Start(){Application.targetFrameRate=120;Time.timeScale=1;feedback?.BindCharacter(characterPresenter);if(pausePanel)pausePanel.SetActive(false);if(pauseSettingsPanel)pauseSettingsPanel.SetActive(false);if(mainMenuConfirmPanel)mainMenuConfirmPanel.SetActive(false);if(gameOverPanel)gameOverPanel.SetActive(false);if(upgradePanel)upgradePanel.SetActive(false);if(characterPanel)characterPanel.SetActive(false);if(PlayerPrefs.GetInt("ReflectableContinue",0)==1){PlayerPrefs.DeleteKey("ReflectableContinue");ContinueGame();}else StartNewRun();}
        bool ValidatePersistentReferences()
        {
            bool valid = true;
            UnityEngine.Object[] required = { gameCamera, player, firePoint, gridOrigin, blocksRoot, projectilesRoot, stageVisualContainer, aimPreview, normalBlockPrefab, gemBlockPrefab, bombBlockPrefab, projectilePrefab, hpText, scoreText, gemsText, turnText, comboText, levelText, characterText, gameOverText, pausePanel, pauseSettingsPanel, mainMenuConfirmPanel, gameOverPanel, upgradePanel, characterPanel, stageIntro, powerButton, ricochetButton, extraBallButton, characterButton, skipTurnButton, pauseButton, characterPresenter, characterGacha, gameplayHud, feedback };
            foreach (var reference in required) if (!reference) { valid = false; break; }
            if (!valid) Debug.LogError("The Game scene contains an unassigned ReflectableGameController reference. Run Tools/Project Validation for the exact field.", this);
            if (characterPresenter && !characterPresenter.Database) { valid = false; Debug.LogError("PlayerCharacterPresenter has no persistent CharacterDatabase reference.", characterPresenter); }
            if (characterGacha && !characterGacha.HasPersistentReferences) { valid = false; Debug.LogError("CharacterGachaUI has missing persistent banner or reveal references.", characterGacha); }
            return valid;
        }
        void Update(){if(gameOver)return;var mouse=Mouse.current;if(Keyboard.current!=null&&Keyboard.current.escapeKey.wasPressedThisFrame){if(mainMenuConfirmPanel&&mainMenuConfirmPanel.activeInHierarchy)CancelMainMenu();else if(pauseSettingsPanel&&pauseSettingsPanel.activeInHierarchy)ClosePauseSettings();else TogglePause();}if(!GameplayInputEnabled||mouse==null)return;Vector3 world=gameCamera.ScreenToWorldPoint(mouse.position.ReadValue());Vector2 dir=(Vector2)(world-firePoint.position);dir.y=Mathf.Max(.2f,dir.y);dir.Normalize();DrawPreview(dir);if(mouse.leftButton.wasPressedThisFrame&&!PointerOverUI())StartCoroutine(Fire(dir));}
        bool GameplayInputEnabled=>state==TurnState.Aiming&&aiming&&Time.timeScale>0&&!AnyModalOpen();
        bool CanSkipTurn=>(state==TurnState.Aiming||state==TurnState.Firing)&&!skippingTurn&&!stageTransitioning&&!gameOver&&Time.timeScale>0&&!AnyModalOpen();
        bool AnyModalOpen()=>(pausePanel&&pausePanel.activeInHierarchy)||(gameOverPanel&&gameOverPanel.activeInHierarchy)||(upgradePanel&&upgradePanel.activeInHierarchy)||(characterPanel&&characterPanel.activeInHierarchy);
